edits.after:
self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {
        // Ignore keyboard navigation if focus is not on the bound field
        if (opts.field && e.target !== opts.field) {
            return;
        }

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                e.preventDefault();
                self.adjustDate('subtract', 1);
                break;
            case 38:
                self.adjustDate('subtract', 7);
                break;
            case 39:
                self.adjustDate('add', 1);
                break;
            case 40:
                self.adjustDate('add', 7);
                break;
        }
    }
};
